import React from 'react';
import './App.css';
import MyProvider from './contexts/MyProvider';
import Main from './components/MainComponent';
import { BrowserRouter } from 'react-router-dom';

function App() {
  return (
    <MyProvider>
      <BrowserRouter>
        <Main />
      </BrowserRouter>
    </MyProvider>
  );
}

export default App;
